import type { gsap as GSAP } from "gsap";

/** One scene of "Doudou and the Moon", generated by doudou-moon/tools/build.py. */
export type DoudouScene = {
  id: string;
  /** Seconds the scene is on screen. */
  slot: number;
  /** Static cut-paper markup (SVG plus a scoped <style>). `__PAPER__` is the paper texture URL. */
  html: string;
  /** Adds every tween to a paused timeline whose time 0 is the scene's first frame. */
  build: (tl: gsap.core.Timeline, g: typeof GSAP) => void;
};
